const roleDefinitions={buyer:{label:'Buyer / Investor',fields:[]},owner:{label:'Property Owner',fields:[]},lawyer:{label:'Lawyer',fields:[]},ca:{label:'Chartered Accountant',fields:[]},broker:{label:'Broker',fields:[]},arbitrator:{label:'Arbitrator',fields:[]},builder:{label:'Builder / Developer',fields:[]},partner:{label:'NV Channel Partner',fields:[],adminOnly:true}};
