const fixtures=[{id:'NV-DEMO-101',category:'Residential',location:'Pune',state:'Maharashtra',area:'4200',unit:'Square Foot',type:'Bungalow',landType:'',buildingType:'Bungalow',availableUnits:'1',status:'published',title:'Residential property',image:'villa.png'},{id:'NV-DEMO-102',category:'Land',location:'Nashik',state:'Maharashtra',area:'3.1',unit:'Acre',type:'Agriculture Land',landType:'Agriculture Land',buildingType:'',availableUnits:'1',status:'published',title:'Agricultural land',image:'land.png'}];
