function audit(r,actor,type,details={}){r.auditTrail||=[];r.auditTrail.push({id:id('ACT'),at:now(),actorId:actor?.id||'system',actorRole:actor?.role||'system',type,details:clone(details)})}
function preview(p){return {id:p.id,category:p.category,location:p.location,state:p.state,area:p.area,unit:p.unit,type:p.type,landType:p.landType,buildingType:p.buildingType,availableUnits:p.availableUnits,title:(p.category||'Property')+' opportunity',image:p.image}}
