function adminScope(actor,record){if(!actor||!['superadmin','subadmin','employee'].includes(actor.role)||actor.active!==true)fail('Staff access required.');if(actor.role==='superadmin')return true;if(actor.role==='subadmin')return !record.subAdminId||record.subAdminId===actor.id;return record.employeeId===actor.id}
function adminRecord(actor,kind,recordId){const d=expire(data()),list=kind==='property'?d.properties:d.enquiries,r=list.find(x=>x.id===recordId);if(!r||kind==='property'&&(!r.ownerId||['draft','expired'].includes(r.status))||!adminScope(actor,r))fail('Request is not available to your team.');return {d,r}}
function startOtp(mobile,mode='auto'){if(!['auto','login','signup'].includes(mode))fail('Choose login or signup.');mobile=String(mobile||'').replace(/\D/g,'');if(!/^\d{10,15}$/.test(mobile))fail('Enter a valid 10–15 digit mobile number.');const exists=data().accounts.some(a=>a.mobile===mobile);if(mode==='login'&&!exists)fail('No account found. Please sign up.');if(mode==='signup'&&exists)fail('This number is registered. Please log in.');const otp={mobile,mode,code:'123456',expires:clock()+config().otpLifetimeMs,attempts:0};write(session,'nirvivad-pending-otp-v1',otp);return {mobile,expires:otp.expires,prototypeCode:'123456'}}
