function current(){const d=data();const u=sessionUser(d);return u?clone(u):null}
function setLastRole(role){const d=data(),u=requireUser(d);if(!u.roles.includes(role))fail('Role is not available.');if(u.lastRole!==role){u.lastRole=role;u.updatedAt=now();save(d)}return role}
function logout(){session.removeItem(SESSION)}
function profile(input){const d=data(),u=requireUser(d);const name=clean(input.name,100),email=clean(input.email,160).toLowerCase();if(name.length<2)fail('Name must have at least 2 characters.');if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))fail('Enter a valid email.');if(email&&d.accounts.some(x=>x.id!==u.id&&x.email===email))fail('Email already in use.');u.name=name;u.email=email;u.updatedAt=now();save(d);return clone(u)}
function addRole(role){if(!roleDefinitions[role]||roleDefinitions[role].adminOnly)fail('Choose a self-join role.');const d=data(),u=requireUser(d);if(!u.name)fail('Complete your basic profile first.');if(!u.roles.includes(role)){u.roles.push(role);u.roleHistory||=[];u.roleHistory.push({role,joinedAt:now()});if(!u.primaryRole)u.primaryRole=role}if(!u.lastRole)u.lastRole=role;u.updatedAt=now();save(d);return clone(u)}
function activatePartner(actor,input){if(!actor||actor.role!=='superadmin'||actor.active!==true)fail('Super Admin access required.');const d=data(),mobile=String(input.mobile||'').replace(/\D/g,'');if(!/^\d{10,15}$/.test(mobile))fail('Enter a valid mobile number.');let u=d.accounts.find(x=>x.mobile===mobile);if(u?.roles.includes('partner'))fail('This account is already an NV Channel Partner.');if(!u){const name=clean(input.name,100),email=clean(input.email,160).toLowerCase();if(name.length<2)fail('Enter the partner account name.');if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))fail('Enter a valid email.');if(email&&d.accounts.some(x=>x.email===email))fail('Email already in use.');u={id:id('USR'),mobile,name,email,roles:[],roleHistory:[],createdAt:now(),updatedAt:now()};d.accounts.push(u)}if(!basicKyc(u)){const aadhaar=String(input.aadhaar||'').replace(/\s/g,''),pan=String(input.pan||'').toUpperCase().trim();if(!/^\d{12}$/.test(aadhaar)||!aadharValid(aadhaar))fail('Enter a valid 12-digit Aadhaar number.');if(!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(pan))fail('Enter a valid PAN format.');u.basicKyc={status:'complete',aadhaarLast4:aadhaar.slice(-4),panMasked:pan.slice(0,2)+'******'+pan.slice(-2),attachments:{},completedAt:now()};syncOwnerKyc(d,u)}u.roles.push('partner');u.professionalProfiles||={};u.professionalProfiles.partner={status:'approved',registrationNumber:'Admin activated',authority:'Nirvivad',qualification:'',enrolmentDocument:'',practiceDocument:'',submittedAt:now(),review:{by:actor.id,at:now(),reason:'Admin-controlled activation'}};u.roleHistory||=[];u.roleHistory.push({role:'partner',joinedAt:now(),by:actor.id});u.primaryRole||=u.roles[0];u.lastRole||='partner';u.updatedAt=now();save(d);return clone(u)}
function isProfessional(role){return ['lawyer','ca','broker','arbitrator','builder','partner'].includes(role)}
function credentialFields(role){return role==='broker'?{registration:'Brokerage registration / credential',authority:'Service area',first:'Brokerage proof',second:'Experience proof'}:role==='arbitrator'?{registration:'Arbitration credential / registration',authority:'Professional body',first:'Qualification proof',second:'Arbitration experience proof'}:role==='builder'?{registration:'Organisation registration',authority:'Representative authority',first:'Authority proof',second:'Project credential'}:{registration:role==='lawyer'?'Bar enrolment number':'ICAI membership number',authority:role==='lawyer'?'State Bar Council':'ICAI branch / category',first:role==='lawyer'?'Enrolment certificate':'Membership certificate',second:'Certificate of Practice'}}
