function submitProfessional(role,input){const d=data(),u=requireUser(d);if(!u.roles.includes(role)||!isProfessional(role)||role==='partner')fail('Professional role is not available.');if(!basicKyc(u))fail('Complete basic KYC first.');const prior=u.professionalProfiles?.[role];if(prior?.status==='approved')fail('Approved profile cannot be edited in this prototype.');const registrationNumber=clean(input.registrationNumber,80),authority=clean(input.authority,120),qualification=clean(input.qualification,160),enrolmentDocument=clean(input.enrolmentDocument,160),practiceDocument=clean(input.practiceDocument,160);if(!registrationNumber||!authority||!enrolmentDocument||!practiceDocument)fail('Registration, authority and both credential document names are required.');u.professionalProfiles||={};u.professionalProfiles[role]={status:'submitted',registrationNumber,authority,qualification,enrolmentDocument,practiceDocument,submittedAt:now(),review:null};u.updatedAt=now();save(d);return clone(u.professionalProfiles[role])}
function listCustomers(actor){if(!actor||actor.role!=='superadmin'||actor.active!==true)fail('Super Admin access required.');return data().accounts.map(u=>({id:u.id,name:u.name,mobile:u.mobile,email:u.email,demo:!!u.demo,primaryRole:u.primaryRole||u.roles[0]||null,roleHistory:clone(u.roleHistory||u.roles.map((role,i)=>({role,joinedAt:i===0?u.createdAt:null}))),basicKyc:basicKyc(u)?{status:'complete',aadhaarLast4:basicKyc(u).aadhaarLast4,panMasked:basicKyc(u).panMasked}: {status:'pending'},professionalProfiles:clone(u.professionalProfiles||{}),createdAt:u.createdAt}))}
function reviewProfessional(actor,accountId,role,decision,reason=''){if(!actor||actor.role!=='superadmin'||actor.active!==true)fail('Super Admin access required.');if(!isProfessional(role)||role==='partner'||!['approved','rejected'].includes(decision))fail('Choose a valid decision.');const d=data(),u=d.accounts.find(x=>x.id===accountId);if(!u||!u.roles.includes(role))fail('Customer not found.');const profile=u.professionalProfiles?.[role];if(!profile||profile.status!=='submitted')fail('Only submitted profiles can be reviewed.');if(decision==='rejected'&&!clean(reason,500))fail('Provide a reason for rejection.');profile.status=decision;profile.review={by:actor.id,at:now(),reason:clean(reason,500)};u.updatedAt=now();save(d);return clone(profile)}
function listMine(){const d=expire(data()),u=requireUser(d);return d.properties.filter(p=>p.ownerId===u.id).map(customer)}
function property(input,recordId,submit=false){const d=expire(data()),u=requireUser(d);if(!u.roles.includes('owner'))fail('Property Owner role required.');let p=recordId?d.properties.find(x=>x.id===recordId):null;if(recordId&&(!p||p.ownerId!==u.id||p.status!=='draft'))fail('Only your active draft can be edited.');if(!p){p={id:id('NV'),ownerId:u.id,createdAt:now(),status:'draft',statusHistory:[],assignmentHistory:[],followUps:[],requests:[],internalRemarks:[],activity:[],kyc:{aadhaar:'pending',pan:'pending'},subscription:{status:'pending',planId:null}};d.properties.push(p)}
for(const k of ['title','category','state','location','locality','description','type','landType','buildingType','ownershipType','disputeType','area','unit','availableUnits'])if(input[k]!==undefined)p[k]=clean(input[k],k==='description'?1200:120);
if(submit){for(const k of ['title','category','state','location','area','unit','ownershipType'])if(!p[k])fail(k+' is required before submission.');if(!Number.isFinite(Number(p.area))||Number(p.area)<=0)fail('Area must be positive.');p.status="submitted";p.kyc={aadhaar:"pending",pan:"pending"};p.submittedAt=now();p.expiresAt=null;p.statusHistory.push({status:"submitted",at:now()});p.activity.push({message:"Property submitted for review. Nirvivad will update you after review.",visible:true,at:now()})}else if(!p.expiresAt)p.expiresAt=draftExpiry();audit(p,{id:u.id,role:'owner'},submit?'property_submitted':'draft_saved',{fields:Object.keys(input).filter(k=>input[k])});syncOwnerKyc(d,u);p.updatedAt=now();save(d);return customer(p)}
function propertyStep(recordId,step){const d=expire(data()),u=requireUser(d),p=d.properties.find(x=>x.id===recordId&&x.ownerId===u.id&&x.status==='draft');if(!p)fail('Draft unavailable.');if(!['Property','Location','Ownership','Review'].includes(step))fail('Unknown property step.');if(!(p.auditTrail||[]).some(x=>x.type==='step_completed'&&x.details.step===step))audit(p,{id:u.id,role:'owner'},'step_completed',{step});p.updatedAt=now();save(d);return customer(p)}
function basicKyc(u){return u.basicKyc?.status==='complete'?u.basicKyc:Object.values(u.kycByRole||{}).find(k=>k?.status==='complete'&&k.aadhaarLast4&&k.panMasked)||null}
function roleKyc(role){const u=requireUser(data());if(!u.roles.includes(role))fail('Add this role before viewing KYC.');const basic=basicKyc(u),specific=u.kycByRole?.[role]||{};return clone(basic?{...basic,qualifications:specific.qualifications||{},basicShared:true}:{status:'pending'})}
function syncOwnerKyc(d,u){const k=basicKyc(u);if(!k)return;for(const p of d.properties.filter(p=>p.ownerId===u.id)){if(p.kyc?.aadhaar!=='verified')audit(p,{id:u.id,role:'owner'},'basic_kyc_linked',{status:'complete'});p.kyc={aadhaar:'verified',pan:'verified',aadhaarLast4:k.aadhaarLast4,panMasked:k.panMasked};if(p.status==='eligible_for_deal'){p.status='subscription_pending';p.statusHistory.push({status:p.status,at:now()});p.activity.push({message:'Property eligibility confirmed. Basic KYC is complete; choose a subscription plan to continue.',visible:true,at:now()})}}}
function submitRoleKyc(role,input){const d=expire(data()),u=requireUser(d);if(!roleDefinitions[role]||!u.roles.includes(role))fail('Add this role before viewing KYC.');const prior=basicKyc(u);if(prior){if(!u.basicKyc){u.basicKyc={status:'complete',aadhaarLast4:prior.aadhaarLast4,panMasked:prior.panMasked,attachments:prior.attachments||{},completedAt:prior.completedAt||now()};syncOwnerKyc(d,u);save(d)}return roleKyc(role)}const aadhaar=String(input.aadhaar||'').replace(/\s/g,''),pan=String(input.pan||'').toUpperCase().trim();if(!/^\d{12}$/.test(aadhaar)||!aadharValid(aadhaar))fail('Enter a valid 12-digit Aadhaar number.');if(!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(pan))fail('Enter a valid PAN format.');const attachments={};for(const key of ['aadhaarImage','panImage']){const file=input[key];if(file&&file.name){if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>5*1024*1024)fail('Attachments must be JPG, PNG, WebP or PDF, up to 5 MB.');attachments[key]={name:clean(file.name,160),type:file.type,size:file.size}}}u.basicKyc={status:'complete',aadhaarLast4:aadhaar.slice(-4),panMasked:pan.slice(0,2)+'******'+pan.slice(-2),attachments,completedAt:now()};u.updatedAt=now();syncOwnerKyc(d,u);save(d);return roleKyc(role)}
